General structure:
#include <stdio.h>
/* The main function. */
int main(void){
    printf("Hello World!\n");
    return 0;
}

Presetted values:
void test(foo_t f) {
    f.a = 22; // f is a full shallow copy of x, doesn't affect x
}
foo_t x;
x.a = 11;
x.b = x.a + 1;
test(x);
-> x: {a: 11, b: 12} (in stack)

void test(foo_t *f) {
    f->a = 22;
}
foo_t *p = &x; // p is a pointer to x
p->a = 21;
p->b = 22;
test(&x);
(The component of a struct can be reached using a pointer and the -> notation)

foo_t *test() {
    foo_t f;
    f.a = 21;
    f.b = 22;
    return &f; // nooooo!!!!!
}

foo_t *p = test();
(*p becomes a dangling pointer -> causes undefined behavior/segmentation fault, f lives only inside the stack frame of test() the moment test() returns, that stack frame is gone.)

General structure:
int x = 0;
if(x)
    printf("true");
if(x){
    printf("true");
    x = 1;
}

int op = 3;
int z = 0;
switch(op){
    case 1:
        z=10
        break;
    case 2:
        z=20
        break;
    default:
        z=40;
}

int x = 0;
while(x < 10){
    x++;
    printf("%d\n",x);
}

int x = 0;
while(1){
    if(x >= 10)
    break;
    x++;
    printf("%d\n",x);
}

int x = 0;
do{
    x++;
    printf("%d\n",x);
}while(x < 10);

for(int i=0; i<128; i++){
    printf("%3d %3x %c\n",i,i,i);
}

struct compound{
    int x;
