    int z;
}

Presetted values:
// Variant 1
void test1(int f[]) { f[1] = 21; }
// Variant 2
void test2(int *f) { f[1] = 21; }
// Variant 3
void test3(int *f) {*(f + 1) = 21;}
int foo[5] = {0,1,2,3,4};
test(foo);
-> foo = {0, 21, 2, 3, 4}

int a[10];
a[2] = 3; // writing to offset 2
foo[20] = 666; // writing to offset 20, maximum is 10 and does not belong to its intended allocation

General structure:
int foo(int x, int y) {
    return x + y;
}
int bar() {
    int z;
    z = foo(3, 4)
    return z;
}

-> {(stack frame of bar)} -> {(stack frame of bar) -> (stack frame of foo)} -> {(stack frame of bar)}

The arguments to a procedure are provided as copies of the value, i.e. "call by value".
int foo(int a, int b) {
    return a + b;
}

int * this_is_the_way() { // Can include pointers as return values
    int * foo = (int * ) malloc(4 * sizeof(int));
    for (int i = 0; i < 4; i++) {
        foo[i] = i;
    }
    return foo;
}
int main() {
    int * ret = this_is_the_way();
}

int generic(int * arr, int n, int init, int (*op)(int, int)) {
    int gen = init;
    for (int i = 0; i < n; i++)
        gen = op(gen, arr[i]);
    return gen;
}

int add (int x , int y ) {
    return x + y ;
}
int mul (int x , int y ) {
    return x * y ;
}
int main() {
    int arr[] = {1, 2, 3, 4, 5};
    printf(" sum : %d \n ", generic(arr, 5, 0, add));
    printf(" product : %d \n ", generic(arr, 5, 1, mul));
    int(*x)(int, int) = add; // function as type
    printf("x(3,4) = %d\n ", x(3, 4));
}

